M = [
{"id":"tahiyyetulmescid","yol":["Namaz","Vitir, cemaat ve secdeler"],"baslik":"Tahiyyetü’l-mescid namazı","ar":"تحية المسجد",
 "hanefi":"Mescide giren kişinin oturmadan önce iki rekât kılması müstehaptır. Kerahet vakitlerinde kılınmaz; o vakitte giren tesbih, tehlil ve salavatla meşgul olur. Mescide girip hemen farz veya başka bir namaz kılan için o namaz tahiyye yerine geçer.",
 "mez":{"maliki":["Mendup","Kerahet vakitlerinde kılınmaz; hatip minberdeyken de kılınmaz."],
        "safii":["Sünnet","Sebepli namaz olduğundan kerahet vakitlerinde de kılınır; hutbe okunurken giren kısa iki rekât kılar."],
        "hanbeli":["Sünnet","Kerahet vaktinde kılınıp kılınmayacağı hakkında iki rivayet vardır; hutbe sırasında giren kısa kılar."]},
 "sebep":"Tahiyye hadisinin genel ifadesi ile kerahet vakitlerinde namazı yasaklayan hadislerin hangisinin özel tutulacağı (tahsis) meselesi.",
 "delil":[["hadis","“Biriniz mescide girince oturmadan önce iki rekât kılsın.”",hadis("فليركع ركعتين قبل أن يجلس"),"Buhârî, Salât, 60; Müslim, Salâtü’l-müsâfirîn, 69."],
          ["hadis","Kerahet vakitlerinde namaz yasağı",hadis("لا صلاة بعد الصبح حتى ترتفع الشمس"),"Buhârî, Mevâkît, 30; Müslim, Müsâfirîn, 288."]],
 "usul":"İki âm (genel) nas çatıştığında Hanefîler yasak bildiren nassı ihtiyaten öne alır (muharrim mübihe takdim edilir); Şâfiîler ise sebebi olan namazları yasağın kapsamı dışında tutar."},
{"id":"namazdaaglama","yol":["Namaz","Namazın kılınışı"],"baslik":"Namazda ağlamak","ar":"البكاء في الصلاة",
 "hanefi":"Cennet, cehennem ve Allah korkusu sebebiyle ağlamak, sesli olsa bile namazı bozmaz; huşûnun alametidir. Dünyevî bir acı veya üzüntü yüzünden sesli ağlayıp harfler çıkarmak namazı bozar.",
 "mez":{"maliki":["Huşûdan olursa bozmaz","Dünyevî sebeple sesli ağlamak konuşma hükmündedir; az olursa sehiv secdesi, çok olursa namazı bozar."],
        "safii":["İki harf çıkarsa bozar","Sebebi ister ahiret ister dünya olsun, iki harf ya da anlamlı bir harf ortaya çıkarsa namaz bozulur; yalnız gözyaşı bozmaz."],
        "hanbeli":["Allah korkusundan bozmaz","Elinde olmadan ve Allah korkusundan ise bozmaz; aksi hâlde iki harf çıkarsa bozar."]},
 "sebep":"Ağlamanın konuşma sayılıp sayılmayacağı; Hz. Peygamber’in namazda ağladığını bildiren rivayetin hangi durumu kapsadığı.",
 "delil":[["hadis","Hz. Peygamber’in namazda ağlaması",hadis("ولصدره أزيز كأزيز المرجل من البكاء"),"Ebû Dâvûd, Salât, 157; Nesâî, Sehv, 18: “Göğsünden, kaynayan kazan gibi ağlama sesi geliyordu.”"],
          ["ayet","Meryem 19:58","./#19-58","“Rahmân’ın ayetleri okunduğunda secdeye kapanarak ve ağlayarak yere düşerlerdi.”"]],
 "usul":"Hanefîler fiilin sebebine bakar: ahirete yönelik ağlama namazın amacına (huşû) uygundur, dünyevî ağlama ise insanların konuşması (kelâmü’n-nâs) gibidir."},
{"id":"ayakkabinamaz","yol":["Namaz","Vakitler ve şartlar"],"baslik":"Ayakkabıyla namaz kılmak","ar":"الصلاة في النعلين",
 "hanefi":"Ayakkabı temiz ise onunla namaz kılmak caizdir. Mescidin halısını ve temizliğini korumak, cemaati rahatsız etmemek gerektiğinden bugün camilerde ayakkabı çıkarılır; bu, örfe ve maslahata uygundur.",
 "mez":{"maliki":["Caiz","Temiz olduğu bilinen ayakkabıyla namaz caizdir."],
        "safii":["Caiz","Ayakkabının temiz olması şarttır."],
        "hanbeli":["Caiz, hatta bazılarına göre müstehap","Yahudilere muhalefet hadisine dayanarak müstehap görenler vardır; temizlik şarttır."]},
 "sebep":"Hz. Peygamber’in ayakkabıyla namaz kıldığına dair rivayetlerin teşrî mi (sünnet) yoksa caizliği gösteren fiil mi olduğu; mescitlerin zemini değiştikçe örfün değişmesi.",
 "delil":[["hadis","Ayakkabıyla namaz",hadis("أكان النبي صلى الله عليه وسلم يصلي في نعليه"),"Enes’e “Hz. Peygamber ayakkabısıyla namaz kılar mıydı?” diye soruldu, “Evet” dedi (Buhârî, Salât, 24)."],
          ["hadis","Ayakkabıdaki pisliğin silinmesi",hadis("فإن رأى في نعليه قذرا أو أذى فليمسحه وليصل فيهما"),"Ebû Dâvûd, Salât, 89."]],
 "usul":"Hz. Peygamber’in fiilleri her zaman sünnet değil, bazen ibâha (caizlik) bildirir. Örf ve maslahat, mubah alandaki uygulamayı belirler."},
{"id":"ezancevap","yol":["Namaz","Ezan ve kamet"],"baslik":"Ezanı işitenin cevap vermesi","ar":"إجابة المؤذن",
 "hanefi":"Ezanı işiten kişinin müezzinin sözlerini tekrar etmesi (sözlü icabet) menduptur; “hayye ale’s-salâh” ve “hayye ale’l-felâh”ta “lâ havle ve lâ kuvvete illâ billâh” der. Cemaate gitmek (fiilî icabet) ise erkekler için cemaatin hükmüne göredir. Ezandan sonra salavat ve vesîle duası okunur.",
 "mez":{"maliki":["Müstehap","Sözlü icabet müstehaptır; şehadetlerin sonuna kadar tekrar etmekle yetinilebilir."],
        "safii":["Sünnet","Namazda olan cevap vermez, namazdan sonra kısaca tekrar eder."],
        "hanbeli":["Sünnet","Namazda olan cevap vermez; Kur’an okuyan ara verip cevap verir."]},
 "sebep":"“Müezzinin dediğini deyin” emrinin vücûb mu nedb mi ifade ettiği.",
 "delil":[["hadis","“Ezanı işittiğinizde müezzinin dediğinin benzerini söyleyin.”",hadis("إذا سمعتم النداء فقولوا مثل ما يقول المؤذن"),"Buhârî, Ezan, 7; Müslim, Salât, 10."],
          ["hadis","Vesîle duası",hadis("اللهم رب هذه الدعوة التامة"),"Buhârî, Ezan, 8."]],
 "usul":"Emir sîgası aslen vücûb ifade eder; ancak Hz. Peygamber’in ezanı duyup cevap vermediği rivayetler gibi karineler emri nedbe (tavsiyeye) çevirir."},
{"id":"secdetsukur","yol":["Namaz","Vitir, cemaat ve secdeler"],"baslik":"Şükür secdesi","ar":"سجدة الشكر",
 "hanefi":"Ebû Hanîfe’den, nimete şükrün namaz kılmakla yapılmasının daha uygun olduğu nakledilir; fetva ise Ebû Yûsuf ve İmam Muhammed’in görüşüne göredir: Bir nimete kavuşan veya bir musibetten kurtulan kişinin tek secde ile şükretmesi müstehaptır. Kıbleye dönülür, abdest gerekir; namazdan sonra adet hâline getirmek mekruhtur.",
 "mez":{"maliki":["Mekruh (meşhur görüş)","İmam Mâlik şükür secdesini mekruh görmüştür; bazı Mâlikîler caiz sayar."],
        "safii":["Sünnet","Yeni bir nimet veya kurtuluş anında namaz dışında yapılır; tilâvet secdesi şartları aranır."],
        "hanbeli":["Sünnet","Nimet ve kurtuluş anında yapılır; namaz içinde yapılırsa namaz bozulur."]},
 "sebep":"Hz. Peygamber’den ve sahabeden şükür secdesine dair rivayetlerin sıhhati ve Hz. Peygamber’in her nimette secde etmediğinin delil sayılıp sayılmayacağı.",
 "delil":[["hadis","Sevindirici bir haber gelince secdeye kapanması",hadis("كان إذا جاءه أمر سرور أو بشر به خر ساجدا"),"Ebû Dâvûd, Cihâd, 162; Tirmizî, Siyer, 25."]],
 "usul":"Fiilî sünnetin delâleti ve haber-i vâhidin umûmü’l-belvâ (sık karşılaşılan) konularda kabul edilip edilmeyeceği tartışması."},
]
